#include <vector>
#include <stdexcept>
#include <iostream>

int main() {
    std::vector<int> v = {10, 20, 30};

    // Safe access (throws exception if index 5 is invalid)
    try {
        int val = v.at(2); // OK: val = 30
        // v.at(5); // Would throw std::out_of_range
    } catch (const std::out_of_range& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    // Unchecked access (fastest but potentially UB)
    v[1] = 25; // OK: v = {10, 25, 30}
    // v[5] = 99; // DANGER: Undefined Behavior!
}
